scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0

    # Compare all pairs (i, j) where i < j
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute n! mod mod
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.lcg_rounds:
def solve(inputs: dict) -> float:
    x = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    # Apply the LCG formula k times
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

